package com.bedlessfighter.necroManager.commands;
import com.bedlessfighter.necroManager.managers.MessageManager;import com.bedlessfighter.necroManager.managers.PermissionManager;import org.bukkit.Bukkit;import org.bukkit.command.*;import org.jetbrains.annotations.NotNull;
public final class BroadcastCommand implements CommandExecutor {public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String @NotNull [] a){if(a.length==0){MessageManager.sendRaw(s,MessageManager.prefix()+" &cUsage: /broadcast <message>");return true;}if(!PermissionManager.has(s,"necromanager.broadcast")){MessageManager.send(s,"messages.no-perm","&cYou don't have enough permissions to issue this command!");return true;}String msg=String.join(" ",a);Bukkit.broadcastMessage(MessageManager.color(MessageManager.configured("messages.broadcast","&6[Announcement] &f%message%").replace("%message%",msg)));return true;}}